      "id": "W1",
      "title": "Order Processing and Inventory Record Maintenance",
      "bullets": [
        "Processed incoming orders, checked required paperwork for completeness, and coordinated with relevant departments to resolve missing information before fulfillment.",
        "Maintained inventory records, reconciled delivery documents against received goods, and escalated discrepancies through established procedures for follow-up."
      ]
    }
  ],
  "projects": [
    {
      "id": "T1",
      "title": "Bag-of-Words Baseline for Review Sentiment Classification",
      "bullets": [
        "Implemented a multinomial naive Bayes baseline with bag-of-words features for sentiment classification, using separate training and validation partitions.",
        "Compared unigram and bigram feature configurations under the same evaluation procedure, reviewing misclassified examples involving negation and mixed sentiment."
      ]
    }
  ]
